def smallest_change(arr):
  n = len(arr)
  left, right = 0, n-1

  while left < right:
    if arr[left] == arr[right]:
      left += 1
      right -= 1
    else:
      break

  if left >= right:
    return 0

  min_changes = float('inf')

  for i in range(left, right+1):
    new_arr = arr[:] # make a copy of the original array
    new_arr[i] = arr[right - (i-left)] # change the element at index i to match the corresponding element from the other side
    min_changes = min(min_changes, 1 + smallest_change(new_arr))

  return min_changes
```

