      raise ValueError("Invalid input: n must be non-negative")

  cache = {0: 0, 1: 0, 2: 2} # Initialize cache with first three values

  def helper(n):
      if n in cache:
          return cache[n]
      else:
          result = helper(n - 1) + helper(n - 2) + helper(n - 3) + helper(n - 4)
          cache[n] = result # Cache the result for future use
          return result

  return helper(n)
